src='''from collections import Counter, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out
    background = counts.most_common(1)[0][0]

    # Treat each non-background colored patch as a marker.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, background) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            components.append((color, min(rs), max(rs), min(cs), max(cs)))

    # The most common marker color is the repeated filler; connect the other colors.
    marker_counts = Counter(color for color, *_ in components)
    filler = marker_counts.most_common(1)[0][0] if marker_counts else None
    by_color = defaultdict(list)
    for comp in components:
        color, r0, r1, c0, c1 = comp
        if color != filler:
            by_color[color].append(comp)

    for color, comps in by_color.items():
        for i, a in enumerate(comps):
            _, ar0, ar1, ac0, ac1 = a
            for b in comps[i+1:]:
                _, br0, br1, bc0, bc1 = b
                if ar0 == br0 and ar1 == br1 and (ac1 < bc0 or bc1 < ac0):
                    left, right = (ac1, bc0) if ac1 < bc0 else (bc1, ac0)
                    for rr in range(ar0, ar1+1):
                        for cc in range(left+1, right):
                            if out[rr][cc] == 0:
                                out[rr][cc] = color
                if ac0 == bc0 and ac1 == bc1 and (ar1 < br0 or br1 < ar0):
                    top, bottom = (ar1, br0) if ar1 < br0 else (br1, ar0)
                    for rr in range(top+1, bottom):
                        for cc in range(ac0, ac1+1):
                            if out[rr][cc] == 0:
                                out[rr][cc] = color
    return out
'''
